    private static void tablePayloadSurvivesTheCodec(GameTestHelper helper) {
        Setup setup = setup(helper, 2);
        Fixtures.plant(PlanterTests.planter(helper, setup.rig(), 0), 4, 4, 4);
        waitUntilFormed(helper, setup, () -> {
