            }
        } else {
            Ae2AbsentTests.register(cases);
        }
        return cases;
    }

    public static void register(IEventBus modEventBus) {
        DeferredRegister<MapCodec<? extends GameTestInstance>> instanceTypes =
                DeferredRegister.create(Registries.TEST_INSTANCE_TYPE, ModularPlanters.MOD_ID);
        instanceTypes.register("case", () -> CaseInstance.CODEC);
        instanceTypes.register(modEventBus);
        modEventBus.addListener(MPTestRegistration::registerTests);
    }

    private static void registerTests(RegisterGameTestsEvent event) {
        Holder<TestEnvironmentDefinition<?>> environment = event.registerEnvironment(id("default"));
        CASES.forEach((name, testCase) -> event.registerTest(id(name),
                new CaseInstance(name, new TestData<>(environment, STRUCTURE, testCase.maxTicks(), 0, true))));
    }

    private static Identifier id(String path) {
        return Identifier.fromNamespaceAndPath(ModularPlanters.MOD_ID, path);
    }

    private static final class CaseInstance extends GameTestInstance {
        static final MapCodec<CaseInstance> CODEC = RecordCodecBuilder.mapCodec(instance -> instance.group(
                Codec.STRING.fieldOf("case").forGetter(test -> test.name),
                TestData.CODEC.forGetter(CaseInstance::info)
        ).apply(instance, CaseInstance::new));

        private final String name;

        CaseInstance(String name, TestData<Holder<TestEnvironmentDefinition<?>>> data) {
            super(data);
            this.name = name;
        }

        @Override
        public void run(GameTestHelper helper) {
            CASES.get(name).body().accept(helper);
        }

        @Override
        public MapCodec<CaseInstance> codec() {
            return CODEC;
        }

        @Override
        protected MutableComponent typeDescription() {
            return Component.literal("Modular Planters case");
        }
    }
}
package io.github.julianperge.modular_planters.assets;

import org.junit.jupiter.api.Test;

import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Stream;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class TexturesExistTest {
    private static final Path MODELS = Path.of("src/generated/resources/assets/modular_planters/models/block");
    private static final Path TEXTURES = Path.of("src/main/resources/assets/modular_planters/textures/block");
    private static final Pattern REFERENCE = Pattern.compile("\"modular_planters:block/([a-z0-9_]+)\"");

    @Test void everyModelTextureExistsAndIsSixteenBySixteen() throws IOException {
        TreeSet<String> names = new TreeSet<>();
        try (Stream<Path> models = Files.list(MODELS)) {
            for (Path model : models.filter(p -> p.toString().endsWith(".json")).toList()) {
                Matcher m = REFERENCE.matcher(Files.readString(model));
                while (m.find()) names.add(m.group(1));
            }
        }
        assertFalse(names.isEmpty(), "no modular_planters textures referenced under " + MODELS);

        List<String> problems = new ArrayList<>();
        for (String name : names) {
            Path png = TEXTURES.resolve(name + ".png");
            if (!Files.isRegularFile(png)) {
                problems.add(name + ": missing " + png);
                continue;
            }
            BufferedImage image = ImageIO.read(png.toFile());
            if (image == null || image.getWidth() != 16 || image.getHeight() != 16) {
                problems.add(name + ": not a 16x16 png");
            }
        }
        assertTrue(problems.isEmpty(), "bad textures: " + problems);
    }
}
package io.github.julianperge.modular_planters.network;

import io.github.julianperge.modular_planters.menu.CoreMenu;
import io.github.julianperge.modular_planters.menu.PlanterMenu;
import net.minecraft.server.level.ServerPlayer;
import net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent;
import net.neoforged.neoforge.network.registration.PayloadRegistrar;

public final class MPNetwork {
    private static final String VERSION = "1";

    private MPNetwork() {
    }

    public static void register(RegisterPayloadHandlersEvent event) {
        PayloadRegistrar registrar = event.registrar(VERSION);
        registrar.playToClient(SeedBinCombosPayload.TYPE, SeedBinCombosPayload.STREAM_CODEC, (payload, context) -> {
            if (context.player().containerMenu instanceof PlanterMenu menu && menu.containerId == payload.containerId()) {
                menu.showCombos(payload.combos());
            }
        });
        registrar.playToClient(CoreTablePayload.TYPE, CoreTablePayload.STREAM_CODEC, (payload, context) -> {
            if (context.player().containerMenu instanceof CoreMenu menu && menu.containerId == payload.containerId()) {
                menu.showTable(payload);
            }
        });
        registrar.playToServer(CoreRequestPayload.TYPE, CoreRequestPayload.STREAM_CODEC, (payload, context) -> {
            if (context.player() instanceof ServerPlayer player) {
                CoreMenu.handle(player, payload);
            }
        });
    }
}

